DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch10$113a5569-100b-425f-91ed-685872557c3f$batch10$) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch10$113a5569-100b-425f-91ed-685872557c3f$batch10$) <> 5 THEN RAISE EXCEPTION 'Explanation changed: PT154-S2-Q4'; END IF; END $guard$;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e CROSS JOIN (VALUES (0, $batch10$Conclusion$batch10$, $batch10$Programs that pay children to read should be viewed with suspicion.$batch10$), (1, $batch10$Evidence$batch10$, $batch10$Paying children to read might get them to read more, but it might teach them to see reading as a chore rather than a source of satisfaction.$batch10$), (2, $batch10$Evaluate$batch10$, $batch10$The editorial notes a possible effect but never says why it's bad. To get to "suspicion," the principle has to make instilling enjoyment of reading the program's goal. Then a program that might teach children to see reading as a chore works against that goal.$batch10$), (3, $batch10$Goal$batch10$, $batch10$The goal of early reading programs should be to instill a love of reading.$batch10$)) v(position,label,body) WHERE e.id=$batch10$113a5569-100b-425f-91ed-685872557c3f$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
